-- Régression pure : aucun nextval, setval ou changement de séquence publique.
BEGIN;
SELECT plan(21);
SELECT is(stock_private.format_production_sequence(1::bigint),'0001','Sequence 1 retains every digit');
SELECT is(stock_private.format_production_sequence(9999::bigint),'9999','Sequence 9999 retains every digit');
SELECT is(stock_private.format_production_sequence(10000::bigint),'10000','Sequence 10000 retains every digit');
SELECT is(stock_private.format_production_sequence(10001::bigint),'10001','Sequence 10001 retains every digit');
SELECT is(stock_private.format_production_sequence(10010::bigint),'10010','Sequence 10010 retains every digit');
SELECT is(stock_private.format_production_sequence(100000::bigint),'100000','Sequence 100000 retains every digit');
SELECT is(stock_private.format_production_sequence(9223372036854775807::bigint),'9223372036854775807','Sequence 9223372036854775807 retains every digit');
SELECT is((SELECT count(DISTINCT stock_private.format_production_sequence(x))::integer FROM unnest(ARRAY[9999,10000,10001,10009,10010,10011,100000]::bigint[]) x),7,'Distinct sequence values retain distinct suffixes');
SELECT is(stock_private.format_production_sequence(NULL::bigint),NULL::text,'Null input stays null');
SELECT ok((SELECT provolatile='i' AND proisstrict AND NOT prosecdef FROM pg_proc WHERE oid='stock_private.format_production_sequence(bigint)'::regprocedure),'Formatter is immutable, strict and invoker');
SELECT ok(NOT has_function_privilege('anon','stock_private.format_production_sequence(bigint)','EXECUTE') AND NOT has_function_privilege('authenticated','stock_private.format_production_sequence(bigint)','EXECUTE') AND NOT has_function_privilege('service_role','stock_private.format_production_sequence(bigint)','EXECUTE'),'Formatter remains private');
SELECT ok(NOT has_function_privilege('anon','public.record_production_v11(uuid,numeric,uuid,text,numeric,text,uuid,boolean,numeric,numeric,text,boolean,public.waste_reason)','EXECUTE') AND has_function_privilege('authenticated','public.record_production_v11(uuid,numeric,uuid,text,numeric,text,uuid,boolean,numeric,numeric,text,boolean,public.waste_reason)','EXECUTE') AND has_function_privilege('service_role','public.record_production_v11(uuid,numeric,uuid,text,numeric,text,uuid,boolean,numeric,numeric,text,boolean,public.waste_reason)','EXECUTE'),'public.record_production_v11 retains caller grants');
SELECT ok(NOT has_function_privilege('anon','public.record_batch_production_v13(jsonb,jsonb)','EXECUTE') AND has_function_privilege('authenticated','public.record_batch_production_v13(jsonb,jsonb)','EXECUTE') AND has_function_privilege('service_role','public.record_batch_production_v13(jsonb,jsonb)','EXECUTE'),'public.record_batch_production_v13 retains caller grants');
SELECT ok(NOT has_function_privilege('anon','public.record_kitchen_production_v6(jsonb)','EXECUTE') AND has_function_privilege('authenticated','public.record_kitchen_production_v6(jsonb)','EXECUTE') AND has_function_privilege('service_role','public.record_kitchen_production_v6(jsonb)','EXECUTE'),'public.record_kitchen_production_v6 retains caller grants');
SELECT ok(NOT has_function_privilege('anon','stock_private.record_production_v9(uuid,numeric,uuid,text,numeric,text,uuid,boolean,numeric,numeric,text,boolean,public.waste_reason)','EXECUTE') AND NOT has_function_privilege('authenticated','stock_private.record_production_v9(uuid,numeric,uuid,text,numeric,text,uuid,boolean,numeric,numeric,text,boolean,public.waste_reason)','EXECUTE') AND NOT has_function_privilege('service_role','stock_private.record_production_v9(uuid,numeric,uuid,text,numeric,text,uuid,boolean,numeric,numeric,text,boolean,public.waste_reason)','EXECUTE'),'stock_private.record_production_v9 remains private');
SELECT ok(NOT has_function_privilege('anon','stock_private.record_batch_production_v12(jsonb,jsonb)','EXECUTE') AND NOT has_function_privilege('authenticated','stock_private.record_batch_production_v12(jsonb,jsonb)','EXECUTE') AND NOT has_function_privilege('service_role','stock_private.record_batch_production_v12(jsonb,jsonb)','EXECUTE'),'stock_private.record_batch_production_v12 remains private');
SELECT ok(NOT has_function_privilege('anon','stock_private.record_kitchen_production_v5(jsonb)','EXECUTE') AND NOT has_function_privilege('authenticated','stock_private.record_kitchen_production_v5(jsonb)','EXECUTE') AND NOT has_function_privilege('service_role','stock_private.record_kitchen_production_v5(jsonb)','EXECUTE'),'stock_private.record_kitchen_production_v5 remains private');
SELECT ok(NOT EXISTS (SELECT FROM unnest(ARRAY['public.record_production_v10(uuid,numeric,uuid,text,numeric,text,uuid,boolean,numeric,numeric,text,boolean,public.waste_reason)','stock_private.record_production_v8(uuid,numeric,uuid,text,numeric,text,uuid,boolean,numeric,numeric,text,boolean,public.waste_reason)','public.record_batch_production_v12(jsonb,jsonb)','stock_private.record_batch_production_v11(jsonb,jsonb)','public.record_kitchen_production_v5(jsonb)','stock_private.record_kitchen_production_v4(jsonb)']) s WHERE to_regprocedure(s) IS NOT NULL),'All replaced signatures are retired');
SELECT ok(pg_get_functiondef('stock_private.record_production_v9(uuid,numeric,uuid,text,numeric,text,uuid,boolean,numeric,numeric,text,boolean,public.waste_reason)'::regprocedure) LIKE '%stock_private.format_production_sequence(nextval(''production_records_seq''))%','Production uses the tested formatter with one sequence value');
SELECT ok(pg_get_functiondef('stock_private.record_batch_production_v12(jsonb,jsonb)'::regprocedure) LIKE '%stock_private.format_production_sequence(nextval(''production_batches_seq''))%','Batch uses the tested formatter with one sequence value');
SELECT ok(pg_get_functiondef('stock_private.record_kitchen_production_v5(jsonb)'::regprocedure) LIKE '%record_batch_production_v13(%','Kitchen targets the current batch wrapper');
SELECT * FROM finish();
ROLLBACK;
